-- =====================================================================
-- Podcast / Streaming Platform Analytics Dataset 
-- Tables: shows, episodes, listeners, listens
-- =====================================================================

DROP DATABASE IF EXISTS podcast_analytics;
CREATE DATABASE podcast_analytics;
USE podcast_analytics;

CREATE TABLE shows (
    show_id      INT PRIMARY KEY AUTO_INCREMENT,
    title        VARCHAR(150) NOT NULL,
    genre        VARCHAR(50)  NOT NULL,
    host_name    VARCHAR(100) NOT NULL,
    launch_date  DATE NOT NULL
);

CREATE TABLE episodes (
    episode_id    INT PRIMARY KEY AUTO_INCREMENT,
    show_id       INT NOT NULL,
    title         VARCHAR(200) NOT NULL,
    release_date  DATE NOT NULL,
    duration_sec  INT NOT NULL,
    FOREIGN KEY (show_id) REFERENCES shows(show_id)
);

CREATE TABLE listeners (
    listener_id        INT PRIMARY KEY AUTO_INCREMENT,
    name                VARCHAR(100) NOT NULL,
    country             VARCHAR(60) NOT NULL,
    signup_date         DATE NOT NULL,
    subscription_type   ENUM('free','premium') NOT NULL
);

CREATE TABLE listens (
    listen_id         INT PRIMARY KEY AUTO_INCREMENT,
    listener_id        INT NOT NULL,
    episode_id         INT NOT NULL,
    listen_date         DATE NOT NULL,
    seconds_listened    INT NOT NULL,
    completed           BOOLEAN NOT NULL,
    FOREIGN KEY (listener_id) REFERENCES listeners(listener_id),
    FOREIGN KEY (episode_id) REFERENCES episodes(episode_id)
);

